BEGIN READ ONLY ISOLATION LEVEL REPEATABLE READ;
WITH observed AS (WITH counts AS (SELECT 'public.users' name, count(*) n FROM public.users UNION ALL SELECT 'public.seasons' name, count(*) n FROM public.seasons UNION ALL SELECT 'public.teams' name, count(*) n FROM public.teams UNION ALL SELECT 'public.standings' name, count(*) n FROM public.standings UNION ALL SELECT 'public.brackets' name, count(*) n FROM public.brackets UNION ALL SELECT 'public.matches' name, count(*) n FROM public.matches UNION ALL SELECT 'public.bracket_scores' name, count(*) n FROM public.bracket_scores UNION ALL SELECT 'public.leagues' name, count(*) n FROM public.leagues UNION ALL SELECT 'public.league_members' name, count(*) n FROM public.league_members UNION ALL SELECT 'public.password_resets' name, count(*) n FROM public.password_resets UNION ALL SELECT 'public.leaderboard_history' name, count(*) n FROM public.leaderboard_history UNION ALL SELECT 'public.leaderboard_history_snapshots' name, count(*) n FROM public.leaderboard_history_snapshots UNION ALL SELECT 'public.leaderboard_history_rows' name, count(*) n FROM public.leaderboard_history_rows) SELECT jsonb_build_object('name','public.'||c.relname,'oid',c.oid,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'rows',(SELECT n FROM counts WHERE name='public.'||c.relname),'structural_md5',md5((jsonb_build_object('class',jsonb_build_array(c.oid,c.relname,c.relkind,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.reloptions),'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attidentity,a.attgenerated,a.attcollation,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.at